contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: send an amount to c.play
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this test contract can forward the requested amount
        require(address(this).balance >= amount);

        // observe before-state
        address bank_before = c.bank(); if (__ESBMC_reverted()) return;
        uint pot_before = c.pot(); if (__ESBMC_reverted()) return;
        uint balance_before = address(c).balance;

        bool reverted;
        // call play and catch revert
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-state
        address bank_after = c.bank(); if (__ESBMC_reverted()) return;
        uint pot_after = c.pot(); if (__ESBMC_reverted()) return;
        uint balance_after = address(c).balance;

        // General invariant:
        // If the call did not revert and the sent amount equals the ticket price (10), then one of two cases must hold:
        // 1) No payout: pot increased by amount and contract balance increased by amount.
        // 2) A payout happened: pot became 0, bank unchanged, and contract balance decreased by (pot_before + amount) - (FEE_AMOUNT)
        //    Since FEE_AMOUNT is 1 and not accessible directly here, we instead assert that when pot becomes 0 the bank stays the same
        //    and the contract balance is strictly less than before+amount (i.e., funds left the contract), which captures that a payout left the contract.
        // We allow any behavior if the call reverted or amount != 10.

        assert(
            reverted || (amount != 10) || (
                // bank must remain same in both non-revert outcomes
                bank_after == bank_before
                && (
                    // Case A: pot increased by amount and contract balance increased by amount
                    (pot_after == pot_before + amount && balance_after == balance_before + amount)
                    ||
                    // Case B: pot reset to 0 and contract balance decreased compared to before+amount (i.e., funds were paid out)
                    (pot_after == 0 && balance_after < balance_before + amount)
                )
            )
        );
    }

    // accept Ether in case c.payable sends to this contract (not needed for C but harmless)
    receive() external payable {}
}

